  if (event.origin !== "https://player.example.com") return;
  const data = event.data;
  if (!data || data.type !== "progress" ||
      !Number.isFinite(data.seconds) || data.seconds < 0) return;
  console.log("收到有效进度", data.seconds);
});

async function loadCourse(url) {
  const response = await fetch(url, { headers: { Accept: "application/json" } });
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  if (response.status === 204) return null;
  const type = response.headers.get("content-type") || "";
  if (!type.includes("application/json")) throw new Error("响应不是 JSON");
  return response.json();
}

